import React, { useState } from "react";
import axios from "axios";

const SlotDivision: React.FC = () => {
  const [width, setWidth] = useState(100);
  const [length, setLength] = useState(200);
  const [ratio, setRatio] = useState(0.6);
  const [result, setResult] = useState<any>(null);

  const generateLayout = async () => {
    const res = await axios.post("http://localhost:5000/api/ml/layout", {
      width,
      length,
      ratio_2w: ratio
    });

    setResult(res.data);
  };

  return (
    <div style={{ padding: 40 }}>
      <h1>Slot Division Model</h1>

      <input
        type="number"
        value={width}
        onChange={(e) => setWidth(Number(e.target.value))}
        placeholder="Width"
      />

      <input
        type="number"
        value={length}
        onChange={(e) => setLength(Number(e.target.value))}
        placeholder="Length"
      />

      <input
        type="number"
        step="0.1"
        value={ratio}
        onChange={(e) => setRatio(Number(e.target.value))}
        placeholder="2W Ratio"
      />

      <button onClick={generateLayout}>Generate</button>

      {result && (
        <pre>{JSON.stringify(result, null, 2)}</pre>
      )}
    </div>
  );
};

export default SlotDivision;
